do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: My Spanish 2 Portfolio and Reflection$j$, $j${"prompt": "Create a Spanish portfolio and reflection of at least 900 words in total, written in English and Spanish. Write the Spanish yourself. You may use a dictionary or your lesson notes, but do not copy a full translation from a translation tool. Do not include your home address, phone number, passwords or other private details, and have a parent, guardian or teacher review your portfolio before you submit it. Proverbs 1:5 says, A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels.\n\nPart 1: My Day. Write a paragraph in Spanish of at least ten sentences about your daily routine using at least five reflexive verbs, three irregular yo verbs, saber and conocer.\nPart 2: My Story. Write a story in Spanish of at least twelve sentences about a childhood memory or a Bible story, using the preterite for events and the imperfect for the scene.\nPart 3: Conversation. Write a dialogue in Spanish of at least twelve lines that includes direct and indirect object pronouns, a comparison, por and para, and at least two formal commands.\nPart 4: Community. Write a dialogue of at least eight lines about travel, directions, a pharmacy visit or an emergency, and explain when a volunteer should call a trained interpreter.\nPart 5: Plans and Careers. Write at least eight sentences in Spanish about your future using the present progressive and the future tense, including a career you may choose.\nPart 6: Letters. Write a formal email and an informal note, five sentences each.\nPart 7: Culture Report. Write at least 150 words in English about one Spanish speaking country, community or tradition, with at least eight Spanish words and a respectful description.\nPart 8: Service Plan. Describe four ways you will use Spanish to serve others honestly and respectfully.\nPart 9: Faith and Reflection. Apply at least three Scripture passages from the King James Version, such as Psalm 78:4, Philippians 4:6, Romans 1:7 or Matthew 25:40, to your study of Spanish and your calling to serve, and explain what you learned, what was hardest and your goal for Spanish 3.", "rubric": "100 points. Part 1: 10 points. Part 2: 15 points. Part 3: 15 points. Part 4: 10 points. Part 5: 10 points. Part 6: 10 points. Part 7: 10 points. Part 8: 5 points. Part 9: 10 points. Accuracy of spelling, accents and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Spanish 2 Portfolio and Reflection$j$);
end
$seed$;
